import {exposeBoxSurfaces} from './surfaces.js';import {syncBodyBatches} from './static-batches.js';
export const surfaceExclusions=view=>new Set([...view.shutters.flatMap(s=>[s.group,s.mesh]).filter(Boolean),...(view.adaptivePortals??[]).map(p=>p.group),...(view.springGates??[]).map(g=>g.mesh),view.bioGroup,view.cabin,view.localCabin]);
function excluded(m,set){for(let p=m;p;p=p.parent)if(set.has(p)||p.userData.target)return true;return false;}
function capture(view,set){const entries=[];view.scene.traverse(m=>{if(!m.isMesh||!m.userData.sourceBox||m.userData.batchProxy||excluded(m,set))return;m.geometry.userData.pinnedSurface=true;entries.push({mesh:m,geometry:m.geometry,internal:!!m.userData.internalSurface,signature:m.userData.surfaceSignature,diagonal:m.userData.diagonalSignature,batchSource:!!m.userData.batchSource});});const bodies=Object.values(view.groups).map(body=>{const group=body.userData.batchGroup;if(group)group.userData.pinnedSurface=true;return{body,group,signature:body.userData.batchSignature};});return{entries,bodies};}
function restore(snapshot){for(const e of snapshot.entries){e.mesh.geometry=e.geometry;Object.assign(e.mesh.userData,{internalSurface:e.internal,surfaceSignature:e.signature,diagonalSignature:e.diagonal,batchSource:e.batchSource});e.mesh.visible=!e.internal&&!e.batchSource;}for(const {body,group,signature}of snapshot.bodies){const old=body.userData.batchGroup;if(old!==group){if(old){body.remove(old);if(!old.userData.pinnedSurface)old.traverse(m=>m.geometry?.dispose());}if(group)body.add(group);}body.userData.batchGroup=group;body.userData.batchSignature=signature;}}
// Six known ABC/open/closed variants are retained (hard cap eight). Door
// changes with identical connector geometry do not cause a global rebuild.
export function updateStaticSurfaces(view){const s=view.sim,trigger=s.phase+':'+(s.shutter>.01)+':'+JSON.stringify(s.doors);if(view.staticSurfaceTrigger===trigger)return;view.staticSurfaceTrigger=trigger;const key=JSON.stringify([s.phase,s.shutter>.01,Object.entries(view.maskGroups).map(([id,g])=>[id,g.userData.adapterSignature]),Object.entries(view.fixedMaskGroups).map(([id,g])=>[id,g.userData.adapterSignature]),s.joints.map(j=>[j.id,j.x,j.y,j.z,j.w,j.d,j.height])]);if(view.geometryVariantKey===key)return;view.geometryVariantKey=key;view.surfaceVariants??=new Map();const snapshot=view.surfaceVariants.get(key);if(snapshot){restore(snapshot);view.updateMetrics.surfaceRestores=(view.updateMetrics.surfaceRestores??0)+1;}else{view.updateMetrics.surfacePasses++;const set=surfaceExclusions(view);exposeBoxSurfaces(view.scene,set);syncBodyBatches(view);if(view.surfaceVariants.size<8)view.surfaceVariants.set(key,capture(view,set));}view.updateMetrics.surfaceCachedStates=view.surfaceVariants.size;}
